            }
        ]
    }


def make_ticket(paths, nonce="nonce-1", secret=SECRET_V1, issuer=ISSUER,
                key_version=1):
    payload = {
        "issuer": issuer,
        "keyVersion": key_version,
        "nonce": nonce,
        "notBefore": 0,
        "notAfter": 10 ** 9,
        "paths": list(paths),
    }
    return compact(
        {"payload": payload,
         "signature": sign_payload(payload, secret)}
    )


def cursor_of(result):
    return {
        "digest": result["digest"],
        "next": result["lastSeq"],
        "tail": result["tail"],
    }


